// 3006. Find Beautiful Indices in the Given Array I

const beautifulIndices = function (s, a, b, k) {
  function indexxx(word, check) {
    const n = word.length;
    const m = check.length;
    let i = 0;
    let arr = [];
    while (i < n) {
      if (word[i] === check[0] && word.slice(i, i + m) === check) {
        arr.push(i);
        i++;
      } else {
        i++;
      }
    }
    return arr;
  }
  const one = indexxx(s, a);
  const two = indexxx(s, b);
  let arr = [];

  for (const no of one) {
    for (const bb of two) {
      if (Math.abs(no - bb) <= k) {
        arr.push(no);
        break;
      }
    }
  }
  return arr;
};

console.log(
  beautifulIndices("isawsquirrelnearmysquirrelhouseohmy", "my", "squirrel", 15)
);
console.log(beautifulIndices("abcd", "a", "a", 4));
console.log(beautifulIndices("lahhnlwx", "hhnlw", "ty", 6));
console.log(beautifulIndices("ocmm", "m", "oc", 3));
